"""Exact source-only current-baseline preservation patch. No runtime actions."""
import hashlib
OLD = "def _refresh_stale_source(job: dict, stale: dict) -> dict:\n    page_url = _history_source_origin(job, stale)\n    if not page_url:\n        raise RuntimeError('Немає сторінки для оновлення джерела.')\n    result = resolve_page(page_url)\n    fresh_sources = result.get('sources') if isinstance(result.get('sources'), list) else []\n    if not fresh_sources:\n        raise RuntimeError('Оновлення не повернуло потоків.')\n    season = _history_source_season(job, stale)\n    stale_episode = str(stale.get('episode') or '')\n    stale_voice = str(stale.get('group') or stale.get('translation') or '')\n    stale_quality = str(stale.get('quality') or '').split(' · ')[0]\n    for source in fresh_sources:\n        source['season'] = season\n        source['history_page_url'] = page_url\n        source['discovery_page_url'] = page_url\n    def rank(source: dict) -> tuple:\n        return (\n            str(source.get('episode') or '') == stale_episode,\n            str(source.get('group') or source.get('translation') or '') == stale_voice,\n            str(source.get('quality') or '').split(' · ')[0] == stale_quality,\n            int(source.get('height') or 0),\n        )\n    fresh = max(fresh_sources, key=rank)\n    if not rank(fresh)[0]:\n        raise RuntimeError('Оновлене джерело не містить обраної серії.')\n    kept = [source for source in job.get('sources') or [] if _history_source_origin(job, source) != page_url]\n    existing_ids = {str(source.get('source_id') or '') for source in kept}\n    for source in fresh_sources:\n        sid = str(source.get('source_id') or '')\n        if not sid or sid in existing_ids:\n            seed = '|'.join((page_url, season, str(source.get('episode') or ''), str(source.get('group') or source.get('translation') or ''), str(source.get('quality') or ''), str(source.get('url') or sid)))\n            source['source_id'] = hashlib.sha256(seed.encode('utf-8')).hexdigest()[:16]\n        existing_ids.add(str(source.get('source_id') or ''))\n    target_key = (str(fresh.get('episode') or ''), str(fresh.get('group') or fresh.get('translation') or ''), str(fresh.get('quality') or ''))\n    job['sources'] = kept + fresh_sources\n    job['stream_refreshed_at'] = int(time.time())\n    job['stream_refresh_page_url'] = page_url\n    _save(job)\n    return next((source for source in fresh_sources if (str(source.get('episode') or ''), str(source.get('group') or source.get('translation') or ''), str(source.get('quality') or '')) == target_key), fresh)"
NEW = 'def _refresh_stale_source(job: dict, stale: dict, *, persist: bool = True) -> dict:\n    """Refresh the owned origin without changing work, episode or selected voice."""\n    page_url = _history_source_origin(job, stale)\n    if not page_url:\n        raise RuntimeError(\'Немає сторінки для оновлення джерела.\')\n    result = resolve_page(page_url)\n    if not isinstance(result, dict) or not isinstance(result.get(\'sources\'), list):\n        raise RuntimeError(\'Оновлення не повернуло потоків.\')\n\n    def identity(row: dict) -> dict:\n        catalog = row.get(\'catalog\') if isinstance(row.get(\'catalog\'), dict) else {}\n        return {key: str(catalog.get(key) or row.get(key)) for key in\n                (\'media_uid\', \'tmdb_id\', \'imdb_id\', \'media_type\')\n                if catalog.get(key) or row.get(key)}\n\n    expected_identity = identity(job)\n    def conflicts(row: dict) -> bool:\n        return any(key in expected_identity and value != expected_identity[key]\n                   for key, value in identity(row).items())\n\n    # The real resolver returns title/poster/sources/errors, without catalog IDs.\n    # Its input is the saved origin of this existing job. Never reidentify by title.\n    if conflicts(result) or (result.get(\'page_url\') and result[\'page_url\'] != page_url):\n        raise RuntimeError(\'Оновлене джерело належить іншому твору.\')\n    season = _history_source_season(job, stale)\n    episode = _history_source_episode(job, stale)\n    voice = str(stale.get(\'group\') or stale.get(\'translation\') or \'\')\n    quality = str(stale.get(\'quality\') or \'\').split(\' · \')[0]\n    candidates = []\n    for row in result[\'sources\']:\n        if not isinstance(row, dict):\n            continue\n        if (not row.get(\'url\') or conflicts(row)\n                or row.get(\'has_drm\') or row.get(\'drm\')\n                or media_discovery.is_trailer_source(row) or _autoplay_is_trailer(row)\n                or bool(row.get(\'live\')) != bool(stale.get(\'live\'))\n                or str(row.get(\'group\') or row.get(\'translation\') or \'\') != voice):\n            continue\n        if any(row.get(key) and row[key] != page_url\n               for key in (\'history_page_url\', \'discovery_page_url\')):\n            continue\n        # Check explicit season before helpers can prefer an SxxEyy URL.\n        explicit = str(row.get(\'season\') or \'\').strip()\n        if season and explicit and explicit != season:\n            continue\n        fresh = dict(row, history_page_url=page_url, discovery_page_url=page_url)\n        if (_history_source_season(job, fresh) != season\n                or _history_source_episode(job, fresh) != episode):\n            continue\n        # When a canonical episode label and URL both exist they must agree.\n        raw_episode = str(row.get(\'episode\') or \'\').strip()\n        if raw_episode and re.fullmatch(r\'(?i)(?:\\d+|(?:сер(?:ія|ия)|episode)\\s*\\d+)\', raw_episode):\n            if _history_source_episode(job, {**fresh, \'url\': \'\'}) != episode:\n                continue\n        if season:\n            fresh[\'season\'] = season\n        candidates.append(fresh)\n    if not candidates:\n        raise RuntimeError(\'Оновлення не містить обраної серії та озвучення.\')\n    def height(source: dict) -> int:\n        try:\n            return max(0, int(source.get(\'height\') or 0))\n        except (ValueError, TypeError, OverflowError):\n            return 0\n    fresh = max(candidates, key=lambda source: (\n        str(source.get(\'quality\') or \'\').split(\' · \')[0] == quality, height(source)))\n    kept = [source for source in job.get(\'sources\') or []\n            if str(source.get(\'source_id\') or \'\') != str(stale.get(\'source_id\') or \'\')]\n    existing_ids = {str(source.get(\'source_id\') or \'\') for source in kept}\n    for source in candidates:\n        sid = str(source.get(\'source_id\') or \'\')\n        if not sid or sid in existing_ids:\n            seed = \'|\'.join((page_url, season, episode, voice,\n                             str(source.get(\'quality\') or \'\'), str(source.get(\'url\') or sid)))\n            source[\'source_id\'] = hashlib.sha256(seed.encode(\'utf-8\')).hexdigest()[:16]\n        existing_ids.add(str(source[\'source_id\']))\n    job[\'sources\'] = kept + candidates\n    job[\'stream_refreshed_at\'] = int(time.time())\n    job[\'stream_refresh_page_url\'] = page_url\n    if persist:\n        _save(job)\n    return fresh'
BEFORE = 'd9c39a39c857c4001933f2dc67aaa92ab067db1d847b4ae287f71450eab85695'
AFTER = '70af15e405e506d6bc4de3d92e545850fdf034aa31cc059bf5885de376106a38'

def patch(source):
    if hashlib.sha256(source.encode()).hexdigest() == AFTER:
        return source
    if hashlib.sha256(source.encode()).hexdigest() != BEFORE or source.count(OLD) != 1:
        raise ValueError("Source baseline differs; preserve current code and review")
    result = source.replace(OLD, NEW, 1)
    if hashlib.sha256(result.encode()).hexdigest() != AFTER:
        raise ValueError("Patched source differs from tested result")
    return result
